sp_widget.client_script:
function CaseLookupWidgetController($scope, $http) {
    /*
     * Case Lookup Widget - client-side AngularJS controller.
     *
     * Implements the case-status-lookup user interaction described in
     * AAP Section 0.4.4 ("Page 2 - Case Status Lookup: a single input
     * (case number) and a result panel that shows status, subject,
     * opened_date when found, or the literal text 'No case found with
     * that number.' when not found.").
     *
     * Exposed properties (template-bound):
     *   c.caseNumber - string; bound to the input field via ng-model.
     *                  Initialized to '' (empty string).
     *   c.result     - object | null; on successful lookup, contains
     *                  exactly { status, subject, opened_date } - the
     *                  three whitelisted fields. null when no successful
     *                  lookup has occurred. Drives the result panel's
     *                  ng-if="c.result".
     *   c.notFound   - boolean; true when the case table was queried and
     *                  held no case with that number - an HTTP 404, any
     *                  other 4xx, or a 200 whose body carried no status.
     *                  Drives the not-found panel's ng-if="c.notFound",
     *                  which renders the AAP Section 0.7.4 verbatim text.
     *   c.errorMessage - string; non-empty only when the lookup could not
     *                  be ANSWERED: a 5xx, a network failure, or the
     *                  client-side timeout expiring. Drives the separate
     *                  service-failure panel. Mutually exclusive with both
     *                  c.result and c.notFound.
     *   c.loading    - boolean; true while the in-flight $http.get
     *                  request is pending. Drives the button's
     *                  ng-disabled and the "Looking up..." text.
     *
     * Exposed method (template-bound):
     *   c.lookup()   - executes the case-status lookup. Issues
     *                  GET /api/x_casemgmt/case_status_lookup?number=<encoded>
     *                  via $http.get() under a LOOKUP_TIMEOUT_MS deadline.
     *                  On success (HTTP 200 with a status), sets c.result
     *                  with the strict 3-field whitelist. On a 4xx, sets
     *                  c.notFound = true so the verbatim not-found message
     *                  is rendered. On a 5xx, a network failure or a
     *                  timeout, sets c.errorMessage instead, because in
     *                  those cases nothing was learned about the case.
     *
     * Design rationale:
     *   - controller-as syntax (`var c = this`) per AAP Section 0.5.1's
     *     widget-authoring conventions and per the sibling confirmation
     *     widget at ./sp_widget_x_casemgmt_case_confirmation_widget.xml.
     *   - $http (NOT fetch): Service Portal widgets run in AngularJS
     *     1.5.x context; $http is the canonical HTTP client. fetch()
     *     would bypass AngularJS's digest cycle and require manual
     *     $scope.$apply() handling.
     *   - encodeURIComponent on the case number: defensive URL escaping.
     *     Even though normal case numbers (CASE0000001) contain no
     *     special characters, defensive encoding prevents URL-injection
     *     attacks if a malicious user submits a crafted string.
     *   - Strict 3-field whitelist on response.data: defense-in-depth.
     *     Even if the server's response somehow contained additional
     *     fields (e.g., due to a future refactor of the Script Include),
     *     this client controller extracts ONLY status/subject/opened_date
     *     so no internal data leaks to the template.
     *   - Verbatim error message in template, NOT echoed from server:
     *     the message "No case found with that number." (AAP Section
     *     0.7.4) is hardcoded in the template via ng-if="c.notFound".
     *     This controller deliberately does NOT pass error.data.error
     *     or error.statusText to the template - the server's error
     *     body is NEVER trusted by the client.
     *   - Identical handling of every 4xx: information-leakage hardening.
     *     404 (not-found) and 400 (bad-request) both set c.notFound =
     *     true, so an attacker cannot distinguish "case not found" from
     *     "invalid input" and gains no case-number enumeration oracle.
     *     A 500, a network failure and an expired deadline set
     *     c.errorMessage instead, because in those cases the case table
     *     was never reached and the verbatim not-found text would be a
     *     false statement about the requester's case.
     *   - c.loading flag: prevents double-lookup race conditions if
     *     the user clicks the button twice quickly, AND drives the
     *     "Looking up..." button text for clear UX feedback.
     */
    var c = this;

    /*
     * Deadline for the lookup request, in milliseconds. Chosen to sit well
     * above any normal round trip to the scripted REST endpoint (measured in
     * tens of milliseconds against the verification instance) while still
     * failing fast enough that a requester is not left staring at a disabled
     * button. See the comment at the $http.get call for why a deadline is
     * appropriate on this read and inappropriate on the sibling widget's POST.
     */
    var LOOKUP_TIMEOUT_MS = 20000;

    // Lookup state. Initialize with safe defaults so the template's
    // ng-if expressions evaluate cleanly even before c.lookup() runs.
    c.caseNumber = '';
    c.result = null;
    c.notFound = false;
    c.errorMessage = '';
    c.loading = false;

    /**
     * Look up the status of a case by its number via the scripted REST
     * endpoint at /api/x_casemgmt/case_status_lookup.
     *
     * Per AAP Section 0.4.4: returns ONLY status, subject, opened_date
     * via strict 3-field whitelist on the response.
     *
     * Per AAP Section 0.7.4: on no-match (HTTP 404 or any other error),
     * the verbatim text "No case found with that number." is rendered
     * by the template. This function MUST NOT echo error.data.error or
     * any server-supplied text.
     */
    c.lookup = function() {
        // Idempotent guard: prevent double-lookup if the user clicks
        // the button or presses Enter while a request is in flight.
        if (c.loading) {
            return;
        }
        // Empty-input guard: do not issue a request if the case number
        // is empty or whitespace-only. The button is also disabled in
        // this case via ng-disabled, but the guard provides defense-
        // in-depth in case the disabled state is bypassed (e.g., by
        // pressing Enter in some edge browsers).
        if (!c.caseNumber || String(c.caseNumber).trim() === '') {
            return;
        }

        // Reset state at the start of every lookup. The three outcome
        // panels are mutually exclusive: at most one of c.result,
        // c.notFound and c.errorMessage is truthy at any time.
        c.loading = true;
        c.result = null;
        c.notFound = false;
        c.errorMessage = '';

        // Build the URL with defensive URL-encoding of the case number.
        // The server-side Script Include x_casemgmt.CasePortalService.
        // lookupCase() trims whitespace and queries by the case 'number'
        // field. encodeURIComponent() handles any whitespace, special
        // characters, or potentially malicious input safely.
        var url = '/api/x_casemgmt/case_status_lookup?number=' + encodeURIComponent(String(c.caseNumber).trim());

        // The deadline below is what stops a lookup hanging indefinitely.
        // Without it, an unresponsive instance leaves c.loading true for as
        // long as the browser is willing to wait, the button stays disabled
        // reading "Looking up...", and the requester has no way to retry
        // short of reloading the page. On expiry AngularJS rejects the
        // promise with status 0, which the error handler reports as a
        // service failure rather than as a missing case.
        //
        // A deadline is safe HERE because this request is a read: retrying it
        // costs nothing and cannot duplicate anything. The sibling submission
        // widget deliberately does NOT set one on its POST, because a
        // submission that succeeds server-side just after the client gives up
        // would tell the requester it failed and invite a second press, which
        // is how duplicate cases get created.
        $http.get(url, { timeout: LOOKUP_TIMEOUT_MS }).then(function(response) {
            // Success path (HTTP 200). The server's REST operation
            // returns { status, subject, opened_date } per its contract -
            // but a ServiceNow Scripted REST API wraps whatever the
            // operation script passes to response.setBody() inside a
            // `result` envelope before it reaches the wire. Measured
            // against the live endpoint, a 200 body is
            //   {"result":{"status":"Draft","subject":"...","opened_date":"..."}}
            // so the three whitelisted values live at
            // response.data.result.*, and reading response.data.* yields
            // undefined - which would have painted a result panel with
            // three blank rows instead of the case's status.
            //
            // The unwrap below prefers the envelope and falls back to the
            // bare body, so it is correct whether or not the envelope is
            // applied (the platform can be configured either way, and a
            // caller may append sysparm_no_envelope).
            c.loading = false;
            var body = (response && response.data && response.data.result) ?
                response.data.result :
                (response ? response.data : null);
            // `status` is mandatory on every case, so its presence is the
            // signal that a real record came back. An empty or
            // status-less body is treated as not-found rather than
            // rendered as a panel of blanks.
            if (body && body.status) {
                // Strict 3-field whitelist (defense-in-depth). Extract
                // ONLY status, subject, opened_date from the response
                // body. Even if the server were misconfigured to return
                // additional fields, this widget would not display them.
                // String() coercion handles undefined/null gracefully -
                // the template renders an empty cell rather than the
                // literal text "undefined" or "null".
                c.result = {
                    status:      String(body.status      || ''),
                    subject:     String(body.subject     || ''),
                    opened_date: String(body.opened_date || '')
                };
                c.notFound = false;
            } else {
                // Defensive: empty or status-less response body on HTTP
                // 200. Treat as not-found rather than rendering an empty
                // result panel.
                // This should not occur in practice (the server always
                // returns a body on 200) but guards against unexpected
                // upstream behavior.
                c.result = null;
                c.notFound = true;
            }
        }, function(error) {
            // Error path. Split in two, because a lookup that was ANSWERED
            // and found nothing is a different fact from a lookup that was
            // never answered.
            //
            //   4xx  -> the request reached the case table and no case with
            //           that number came back. This is the not-found case,
            //           and it renders the AAP Section 0.7.4 verbatim text.
            //           EVERY 4xx maps here, not just 404, so a 400 and a
            //           404 remain indistinguishable to the caller and no
            //           case-number enumeration oracle is created.
            //   5xx,
            //   0/-1 -> the instance failed, the network failed, or the
            //           deadline above expired. Nothing was learned about
            //           the case, so claiming "No case found with that
            //           number." would be a false statement about the
            //           requester's case - and a costly one, because the
            //           requester concludes their case does not exist. This
            //           renders the separate service-failure panel instead.
            //
            // Neither branch echoes error.data.error, error.statusText or any
            // other server-supplied content: both message strings are
            // hardcoded, in this controller and in the template respectively.
            c.loading = false;
            c.result = null;
            var httpStatus = (error && typeof error.status === 'number') ? error.status : 0;
            if (httpStatus >= 400 && httpStatus < 500) {
                c.notFound = true;
                c.errorMessage = '';
            } else {
                c.notFound = false;
                c.errorMessage = 'The case service could not be reached. Please try again in a moment.';
            }
        });
    };
}
